import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow that defines a repeat scheduled trigger at a specific time.

Flow(
    {
        $id: Now.ID['flow_trigger_scheduled_repeat'],
        name: 'Flow - Trigger Scheduled Repeat',
        description: 'Flow used by tests to validate repeat scheduled trigger configuration.',
    },
    wfa.trigger(
        trigger.scheduled.repeat,
        {
            $id: Now.ID['trigger_scheduled_repeat'],
            annotation: 'Repeat scheduled trigger at 20 days, 10 hours, 30 minutes, 15 seconds',
        },
        {
            repeat: Duration({ days: 20, hours: 10, minutes: 30, seconds: 15 }),
        }
    ),
    () => {
        // Empty body; this test focuses on scheduled trigger configuration only
    }
)
